import { Await } from "@kasperrt/smolter/preact";
import { Suspense } from "preact/compat";

interface ReviewsProps {
  reviews: Promise<string[]>;
}

export function Reviews({ reviews }: ReviewsProps) {
  return (
    <Suspense fallback={<p role="status">Loading reviews…</p>}>
      <Await resolve={reviews} errorElement={<p>Reviews are unavailable.</p>}>
        {(items) => <ul>{items.map((item) => <li key={item}>{item}</li>)}</ul>}
      </Await>
    </Suspense>
  );
}
